<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence;
use App\Application\Repositories\DeliveryRepository;
use App\Application\Read\Page;
use App\Application\Exceptions\OperationConflict;
final class PdoDeliveryRepository extends PdoRepository implements DeliveryRepository {
 private function query(string $sql,array $args=[]):\PDOStatement {$s=$this->pdo()->prepare($sql);$s->execute($args);return $s;}
 private function rows(string $sql,array $args=[]):array{return $this->query($sql,$args)->fetchAll();}
 private function insert(string $table,array $data):int{$this->query('INSERT INTO '.$table.'('.implode(',',array_keys($data)).') VALUES('.implode(',',array_fill(0,count($data),'?')).')',array_values($data));return $this->insertedId();}
 private function scope(?array $allowed,string $alias,array &$args):string{if($allowed===null)return '';if(!$allowed)return ' AND 1=0';foreach($allowed as $id)$args[]=self::id($id);return ' AND '.$alias.'.branch_id IN('.implode(',',array_fill(0,count($allowed),'?')).')';}
 private function page(array $rows,int $offset):Page{$more=count($rows)>25;if($more)array_pop($rows);return new Page($rows,25,$offset,$more);}
 public function installed():bool{return (bool)$this->rows("SELECT id FROM schema_migrations WHERE id='20261103100300_register_delivery_permissions'");}
 public function listing(string $q,string $status,?int $branch,?array $allowed,int $offset):Page {
  self::pageBounds(25,$offset);if(strlen($q)>120||($status!==''&&!isset(\App\Domain\Deliveries\DeliveryRules::LABELS[$status])))throw new \InvalidArgumentException('Revisa los filtros.');
  $args=[];$where=$this->scope($allowed,'d',$args);if($q!==''){$where.=" AND (d.folio LIKE ? OR q.folio LIKE ? OR JSON_UNQUOTE(JSON_EXTRACT(v.customer_snapshot,'$.legal_name')) LIKE ?)";$term='%'.str_replace(['\\','%','_'],['\\\\','\\%','\\_'],$q).'%';array_push($args,$term,$term,$term);}if($status!==''){$where.=' AND d.status=?';$args[]=$status;}if($branch){$where.=' AND d.branch_id=?';$args[]=$branch;}
  return $this->page($this->rows("SELECT d.*,q.folio quote_folio,b.name branch_name,u.display_name actor_name,JSON_UNQUOTE(JSON_EXTRACT(v.customer_snapshot,'$.legal_name')) customer_name,(SELECT COUNT(*) FROM delivery_items i WHERE i.delivery_id=d.id) item_count,(SELECT COUNT(*) FROM delivery_items i WHERE i.delivery_id=d.id AND i.received_quantity=i.quantity) completed_items FROM deliveries d JOIN quote_versions v ON v.id=d.quote_version_id JOIN quotes q ON q.id=v.quote_id JOIN branches b ON b.id=d.branch_id JOIN users u ON u.id=d.created_by WHERE 1=1".$where.' ORDER BY d.id DESC LIMIT 26 OFFSET '.(int)$offset,$args),$offset);
 }
 public function find(int $id,?array $allowed=null,bool $lock=false):?array{$args=[$id];$where=$this->scope($allowed,'d',$args);return $this->rows("SELECT d.*,q.id quote_id,q.folio quote_folio,v.version_number,JSON_UNQUOTE(JSON_EXTRACT(v.customer_snapshot,'$.legal_name')) customer_name,b.name branch_name,u.display_name actor_name FROM deliveries d JOIN quote_versions v ON v.id=d.quote_version_id JOIN quotes q ON q.id=v.quote_id JOIN branches b ON b.id=d.branch_id JOIN users u ON u.id=d.created_by WHERE d.id=?".$where.($lock?' FOR UPDATE':''),$args)[0]??null;}
 public function quote(int $version,?array $allowed=null,bool $lock=false):?array{$args=[$version];$where=$this->scope($allowed,'q',$args);return $this->rows('SELECT v.*,q.id quote_id,q.status quote_status,q.current_version,q.branch_id,q.customer_id,q.folio FROM quote_versions v JOIN quotes q ON q.id=v.quote_id WHERE v.id=?'.$where.($lock?' FOR UPDATE':''),$args)[0]??null;}
 public function quoteItems(int $version):array{return $this->rows("SELECT qi.*,u.decimal_places,u.symbol,qi.quantity-COALESCE((SELECT SUM(di.received_quantity) FROM delivery_items di WHERE di.quote_item_id=qi.id),0) pending_quantity,COALESCE((SELECT SUM(di.received_quantity) FROM delivery_items di WHERE di.quote_item_id=qi.id),0) received_quantity,COALESCE((SELECT SUM(di.dispatched_quantity) FROM delivery_items di WHERE di.quote_item_id=qi.id),0) dispatched_quantity,qi.quantity-COALESCE((SELECT SUM(di.quantity) FROM delivery_items di JOIN deliveries d ON d.id=di.delivery_id WHERE di.quote_item_id=qi.id AND d.status<>'cancelled'),0) unallocated_quantity FROM quote_items qi JOIN units u ON u.id=qi.unit_id WHERE qi.quote_version_id=? ORDER BY qi.variant_id,qi.id LIMIT 101",[$version]);}
 public function options(string $q,?array $allowed,int $offset):Page{self::pageBounds(25,$offset);if(strlen($q)>120)throw new \InvalidArgumentException('Búsqueda demasiado larga.');$args=[];$where=$this->scope($allowed,'q',$args);if($q!==''){$where.=' AND q.folio LIKE ?';$args[]='%'.str_replace(['%','_'],['\\%','\\_'],$q).'%';}return $this->page($this->rows("SELECT v.id,q.folio,q.branch_id,b.name branch_name,JSON_UNQUOTE(JSON_EXTRACT(v.customer_snapshot,'$.legal_name')) customer_name FROM quotes q JOIN quote_versions v ON v.quote_id=q.id AND v.version_number=q.current_version JOIN branches b ON b.id=q.branch_id WHERE q.status='accepted' AND v.status='issued' AND EXISTS(SELECT 1 FROM quote_items qi WHERE qi.quote_version_id=v.id AND qi.quantity>COALESCE((SELECT SUM(di.quantity) FROM delivery_items di JOIN deliveries d ON d.id=di.delivery_id WHERE di.quote_item_id=qi.id AND d.status<>'cancelled'),0))".$where.' ORDER BY q.id DESC LIMIT 26 OFFSET '.(int)$offset,$args),$offset);}
 public function items(int $id,bool $lock=false):array{return $this->rows('SELECT di.*,di.quantity-di.received_quantity pending_quantity,di.dispatched_quantity-di.received_quantity pending_receipt,qi.variant_id,qi.unit_id,qi.sku,qi.description,u.symbol,u.decimal_places FROM delivery_items di JOIN quote_items qi ON qi.id=di.quote_item_id JOIN units u ON u.id=qi.unit_id WHERE di.delivery_id=? ORDER BY qi.variant_id,di.id'.($lock?' FOR UPDATE':''),[$id]);}
 public function operation(string $key):?array{return $this->rows('SELECT * FROM delivery_events WHERE operation_key=?',[$key])[0]??null;}
 public function create(array $data):int{return $this->insert('deliveries',$data);}
 public function addItem(int $id,int $quoteItem,string $quantity):int{return $this->insert('delivery_items',['delivery_id'=>$id,'quote_item_id'=>$quoteItem,'quantity'=>$quantity]);}
 public function update(int $id,string $status):void{$this->query("UPDATE deliveries SET status=?,lock_version=lock_version+1,dispatched_at=CASE WHEN ?='in_transit' THEN COALESCE(dispatched_at,UTC_TIMESTAMP(6)) ELSE dispatched_at END,delivered_at=CASE WHEN ?='delivered' THEN UTC_TIMESTAMP(6) ELSE delivered_at END WHERE id=?",[$status,$status,$status,$id]);}
 public function quantity(int $item,string $field,string $value):void{if(!in_array($field,['quantity','prepared_quantity','dispatched_quantity','received_quantity'],true))throw new \LogicException('Invalid quantity field');$this->query('UPDATE delivery_items SET '.$field.'=? WHERE id=?',[$value,$item]);}
 public function allocated(int $quoteItem,?int $exclude=null):string{return (string)$this->query("SELECT COALESCE(SUM(i.quantity),0) FROM delivery_items i JOIN deliveries d ON d.id=i.delivery_id WHERE i.quote_item_id=? AND d.status<>'cancelled' AND d.id<>?",[$quoteItem,$exclude??0])->fetchColumn();}
 public function event(array $data):int{return $this->insert('delivery_events',$data);}
 public function finishEvent(int $id,string $status):void{$this->query('UPDATE delivery_events SET to_status=? WHERE id=?',[$status,$id]);}
 public function eventItem(int $event,int $item,string $qty,?int $movement=null):int{return $this->insert('delivery_event_items',['event_id'=>$event,'delivery_item_id'=>$item,'quantity'=>$qty,'inventory_movement_id'=>$movement]);}
 public function movement(int $eventItem,int $movement):void{$this->query('UPDATE delivery_event_items SET inventory_movement_id=? WHERE id=? AND inventory_movement_id IS NULL',[$movement,$eventItem]);}
 public function history(int $id):array{return $this->rows('SELECT e.*,u.display_name actor_name,ei.quantity,ei.delivery_item_id,ei.inventory_movement_id FROM delivery_events e JOIN users u ON u.id=e.actor_user_id LEFT JOIN delivery_event_items ei ON ei.event_id=e.id WHERE e.delivery_id=? ORDER BY e.id,ei.id',[$id]);}
 public function consumedLocal(int $item):string{return (string)$this->query('SELECT COALESCE(SUM(quantity),0) FROM delivery_reservation_consumptions WHERE reservation_item_id=?',[$item])->fetchColumn();}
 public function consumedTransfer(int $item):string{return (string)$this->query('SELECT COALESCE(SUM(quantity),0) FROM delivery_reservation_consumptions WHERE transfer_item_id=?',[$item])->fetchColumn();}
 public function consume(int $eventItem,?int $local,?int $transfer,string $qty):void{$this->insert('delivery_reservation_consumptions',['event_item_id'=>$eventItem,'reservation_item_id'=>$local,'transfer_item_id'=>$transfer,'quantity'=>$qty]);}
 private function table(string $kind):string{if(!in_array($kind,['vehicles','drivers','delivery_runs'],true))throw new \InvalidArgumentException('Recurso inválido.');return $kind;}
 public function resources(string $kind,?array $allowed,int $offset=0):Page{$table=$this->table($kind);self::pageBounds(25,$offset);$args=[];$where=$this->scope($allowed,'r',$args);return $this->page($this->rows('SELECT r.*,b.name branch_name FROM '.$table.' r JOIN branches b ON b.id=r.branch_id WHERE 1=1'.$where.' ORDER BY r.id DESC LIMIT 26 OFFSET '.(int)$offset,$args),$offset);}
 public function resource(string $kind,int $id,bool $lock=false):?array{return $this->rows('SELECT * FROM '.$this->table($kind).' WHERE id=?'.($lock?' FOR UPDATE':''),[$id])[0]??null;}
 public function saveResource(string $kind,array $data,?int $id,int $expected):int{$table=$this->table($kind);if($id===null)return $this->insert($table,$data);if($kind==='delivery_runs')throw new OperationConflict('Las rutas conservan su configuración histórica.');$sets=[];foreach(array_keys($data)as $k)$sets[]=$k.'=?';$args=array_values($data);array_push($args,$id,$expected);$s=$this->query('UPDATE '.$table.' SET '.implode(',',$sets).',lock_version=lock_version+1 WHERE id=? AND lock_version=?',$args);if($s->rowCount()!==1)throw new OperationConflict('El recurso cambió en otra sesión.');return $id;}
 public function addStop(int $delivery,int $run,int $position):void{$this->insert('delivery_stops',['delivery_id'=>$delivery,'run_id'=>$run,'position'=>$position]);}
 public function stop(int $delivery):?array{return $this->rows('SELECT s.*,r.vehicle_id,r.driver_id,r.scheduled_date,r.name run_name FROM delivery_stops s JOIN delivery_runs r ON r.id=s.run_id WHERE s.delivery_id=?',[$delivery])[0]??null;}
}
